// PRIVACY del client: nessun dato lascia il computer. Oltre a non chiamare il server, qui si BLOCCA in modo tecnico ogni
// richiesta verso le API, verso altri siti o di invio (POST, PUT…): passano solo le letture dei file del programma
// (stessa origine, GET/HEAD) e gli URL locali blob:/data:. Ogni tentativo bloccato finisce in window.__rqBloccati (lo
// controllano i test) e nella console.
if (CLIENT) {
  const BLOCCATI = (window.__rqBloccati = []);
  const permesso = (u, metodo) => {
    if (/^(blob|data):/i.test(u)) return true;
    try { const x = new URL(u, location.href); return x.origin === location.origin && !/^\/api(\/|$)/.test(x.pathname) && /^(GET|HEAD)$/i.test(metodo || 'GET'); } catch { return false; }
  };
  const blocca = (metodo, u) => { BLOCCATI.push(`${metodo} ${String(u).slice(0, 120)}`); console.warn('[privacy] richiesta bloccata nel visualizzatore:', metodo, String(u).slice(0, 120)); };
  const fOrig = window.fetch.bind(window);
  window.fetch = (input, init = {}) => {
    const u = typeof input === 'string' ? input : input?.url || String(input), m = String(init.method || input?.method || 'GET').toUpperCase();
    if (!permesso(u, m)) { blocca(m, u); return Promise.reject(new TypeError('richiesta bloccata: il visualizzatore non invia dati')); }
    return fOrig(input, init);
  };
  const xOpen = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (m, u, ...r) { if (!permesso(String(u), String(m).toUpperCase())) { blocca(String(m).toUpperCase(), u); throw new TypeError('richiesta bloccata: il visualizzatore non invia dati'); } return xOpen.call(this, m, u, ...r); };
  try { navigator.sendBeacon = () => false; } catch {}
  try { window.WebSocket = function () { blocca('WS', arguments[0]); throw new TypeError('connessioni bloccate nel visualizzatore'); }; } catch {}
}
