// chiamata senza sessione: restituisce { ok, stato, dati }
async function inviaAccesso(url, dati) {
  try {
    const r = await fetch(url, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dati) });
    let j = {}; try { j = await r.json(); } catch {}
    return { ok: r.ok, stato: r.status, dati: j };
  } catch { return { ok: false, stato: 0, dati: { errore: 'Connessione non riuscita: riprova.' } }; }
}
function entrato(d, verso = '') {
  impostaUtente(d);
  $('#vista-accesso').hidden = true;
  pronto = Promise.resolve(true);
  if (verso && location.hash !== verso) location.hash = verso; else router();
}
async function conBottone(form, fn) {
  const b = form.querySelector('button[type=submit]'); b.disabled = true;
  try { await fn(); } finally { b.disabled = false; }
}
