function controllaPassword() {
  const p = $('#isc-pw').value, q = $('#isc-pw2').value, el = $('#isc-pw-info');
  const forte = p.length >= 10 && /[A-Za-z]/.test(p) && /[^A-Za-z]/.test(p);
  el.textContent = !p ? 'Almeno 10 caratteri, con lettere e almeno un numero o un simbolo.'
    : !forte ? `Ancora troppo debole: ${p.length < 10 ? `${10 - p.length === 1 ? 'manca 1 carattere' : `mancano ${10 - p.length} caratteri`}` : 'aggiungi un numero o un simbolo'}.`
    : q && q !== p ? 'Le due password non coincidono.' : q ? 'Password valida ✓' : 'Password valida: ripetila qui sopra.';
  el.className = 'muted small pw-info ' + (forte && (!q || q === p) ? 'ok' : p ? 'ko' : '');
  return forte && p === q;
}
