    await MPR.modulo.fusione({ fette, max: FUS.maxVol * (Number($('#fusione-max').value) || 100) / 100, opacita: FUS.opacita, soglia: FUS.soglia, mappa: { nome: mappaFus, punti: MAPPE_PET[mappaFus].punti }, mip3d: !!fette[0].suv || /^(PT|NM)$/.test(fette[0].modalita || '') });
    testoScalaFusione(FUS.maxVol, fette[0].suv);
