$('#fusione-mappa').innerHTML = [...new Set(Object.values(MAPPE_PET).map((m) => m.gruppo))].map((g) => `<optgroup label="${esc(g)}">${Object.entries(MAPPE_PET).filter(([, m]) => m.gruppo === g).map(([k, m]) => `<option value="${k}">${esc(m.nome)}</option>`).join('')}</optgroup>`).join('');
