  for (let y = 0; y < img.rows; y++) for (let x = 0; x < img.cols; x++) {
    const rx = Math.round(o.x + x * ax + y * bx), ry = Math.round(o.y + x * ay + y * by), j = y * img.cols + x;
    out[j] = rx >= 0 && ry >= 0 && rx < rif.cols && ry < rif.rows ? (img.pix[j] * sl + it) - (rif.pix[ry * rif.cols + rx] * rs + ri) : 0;
  }
