  c.fillStyle = '#c7d0dc'; c.textAlign = 'right';
  for (const val of [hi - pad, lo + pad, ...(tc && lo < 0 && hi > 0 ? [0] : [])]) { c.fillText(valore(img, val), L - 4, y(val) + 4); c.fillRect(L - 2, y(val), 2, 1); }
  c.textAlign = 'left'; c.fillText('A', L, h - 6); c.textAlign = 'right'; c.fillText(`B  ${lung.toFixed(1)} mm`, w - R, h - 6); c.textAlign = 'left';
  c.strokeStyle = ARANCIO; c.lineWidth = 1.6; c.beginPath(); v.forEach((val, i) => (i ? c.lineTo(x(i), y(val)) : c.moveTo(x(i), y(val)))); c.stroke();
