const VASI_CAC = [['TCS', 'tronco comune', '#ff6b5b'], ['IVA', 'interventricolare anteriore', '#ffd23c'], ['CX', 'circonflessa', '#7ee787'], ['CD', 'coronaria destra', '#78b4ff']];
