  if (iP < 0 || iA < 0) { avvisoBreve('Le serie del confronto non sono nel caso'); return; }
  const nP = prima != null ? (await geoNoduli(d.precedente.serie))?.[prima] : null, nA = dopo != null ? (await geoNoduli(d.attuale.serie))?.[dopo] : null;
