    fatto[v.id] = V.serie.some((s) => { const n = s.files?.length || 0; if (n < 10) return false; let k = 0; for (let i = 0; i < n; i++) if ((TR.vis.get(`${s._i}:${i}`) || {})[v.id]) k++; return k / n >= 0.7; });
