  box.querySelectorAll('.vai').forEach((b) => { b.onclick = async () => { const v = V.volumi[+b.dataset.i]; await selezionaSerie(v.sIdx, V.attivo, { idx: v.idx }); }; });
  box.querySelectorAll('.via').forEach((b) => { b.onclick = () => { V.volumi.splice(+b.dataset.i, 1); disegnaVolumiLista(); disegna(); }; });
