  l.forEach((v, i) => { if (v.recist) box.querySelector(`.vai[data-i="${i}"]`)?.insertAdjacentHTML('afterend', ` <span class="small muted">RECIST ${virgola(v.recist.lung, 1)} mm (img ${v.recist.j + 1})</span>`); });
