  const linea = (f) => punti.map((p, i) => `${i ? 'L' : 'M'}${sx(xs[i]).toFixed(1)},${f(p).toFixed(1)}`).join('');
  const tacche = (max) => { const e = 10 ** Math.floor(Math.log10(max / 4)), passo = [1, 2, 5, 10].map((k) => k * e).find((k) => max / k <= 5); const out = []; for (let v = 0; v <= max; v += passo) out.push(v); return out; };
  let s = `<svg class="tr-graf" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-label="Diametro e volume nel tempo">`;
  for (const v of tacche(dMax)) s += `<line x1="${m.l}" x2="${W - m.r}" y1="${yd(v)}" y2="${yd(v)}" class="tr-griglia"/><text x="${m.l - 4}" y="${yd(v) + 3}" text-anchor="end" class="tr-d">${+v.toFixed(1)}</text>`;
  for (const v of tacche(vMax)) s += `<text x="${W - m.r + 4}" y="${yv(v) + 3}" class="tr-v">${+v.toPrecision(3)}</text>`;
  s += `<text x="${m.l - 4}" y="10" text-anchor="end" class="tr-d">mm</text><text x="${W - m.r + 4}" y="10" class="tr-v">cm³</text>`;
  s += `<path d="${linea((p) => yd(p.diam))}" class="tr-ld"/><path d="${linea((p) => yv(p.vol))}" class="tr-lv"/>`;
