  for (const [key, lista] of Object.entries(V.misure || {})) for (const m of key.split(':').length > 2 ? [] : lista) {
    if (m.tipo !== 'roi' || m.copia) continue;
    const [si, idx] = key.split(':').map(Number), p = await pannelloDi(si), img = await immagineDi(p, idx);
    const F = formaROI(m); if (F.x1 - F.x0 < 4 || F.y1 - F.y0 < 4) continue;
    const x0 = Math.max(0, Math.floor(F.x0)), x1 = Math.min(img.cols - 1, Math.ceil(F.x1)), y0 = Math.max(0, Math.floor(F.y0)), y1 = Math.min(img.rows - 1, Math.ceil(F.y1));
    const w = x1 - x0 + 1, h = y1 - y0 + 1, val = new Float32Array(w * h).fill(NaN), valori = [];
    for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) { if (!F.dentro(x, y)) continue; const u = img.pix[y * img.cols + x] * img.slope + img.inter; val[(y - y0) * w + x - x0] = u; valori.push(u); }
    out.push({ nome: `ROI · ${studioDi(V.serie[si]).nome || ''} img ${idx + 1}`, tc: img.modalita === 'CT' && !img.suv, f: caratteristiche(valori, [{ w, h, val }], img.modalita === 'CT' && !img.suv) });
  }
  // volumi semiautomatici
