      const img = await immagineDi(p, j); tc = img.modalita === 'CT' && !img.suv;
      let x0 = 1e9, y0 = 1e9, x1 = -1, y1 = -1; for (const i of lista) { const x = i % img.cols, y = (i / img.cols) | 0; if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
