  const z = (q) => q.c[2];
  // ricerca dello spostamento in z che rende più simili i profili di area (passo 2 mm), su tutti gli
  // spostamenti che fanno sovrapporre i due volumi: le coordinate del lettino cambiano da un esame all'altro
  const area = (L, zz) => { let best = null, d = 1e9; for (const q of L) { const dd = Math.abs(z(q) - zz); if (dd < d) { d = dd; best = q; } } return d < 8 ? best.area : null; };
  const zA = A.map(z), zB = B.map(z);
