    while (b - a > 1) { const m = (a + b) >> 1; if (fette[m].d < d) a = m; else b = m; }
    const f = Math.abs(fette[a].d - d) <= Math.abs(fette[b].d - d) ? fette[a] : fette[b];
    const e = [q[0] - f.ipp[0], q[1] - f.ipp[1], q[2] - f.ipp[2]];
    const x = Math.round(dot(e, r) / im0.spCol / f.sx), y = Math.round(dot(e, c) / im0.spRow / f.sy);
    return x < 0 || y < 0 || x >= f.w || y >= f.h ? null : f.v[y * f.w + x];
