    const q = ruotaT(T.R, [p.c[0] - tt[0], p.c[1] - tt[1], p.c[2] - tt[2]]);
    const v = mov.valore(q); if (v == null) continue;
    const bb = Math.max(0, Math.min(B - 1, Math.floor((v - mov.lo) * sc)));
    J[p.b * B + bb]++; ha[p.b]++; hb[bb]++; n++;
