  for (const passoMm of [16, 8, 4, 2]) {
    for (let giro = 0, meglio = true; meglio && giro < 25; giro++) {
      meglio = false;
      for (let ax = 0; ax < 3; ax++) for (const sg of [-1, 1]) {
        const t = best.t.slice(); t[ax] += sg * passoMm;
        const r = nmiCon(punti, VM, t); if (r.nmi > best.nmi + 1e-5) { best = { t, nmi: r.nmi }; meglio = true; }
      }
    }
    await cedi();
  }
  return { t: best.t, nmi: best.nmi, iniziale, VR };
