// 11/11: coregistrazione di due studi = traslazione (NMI a 4 mm) + rotazione (6 gradi di libertà). Senza la rotazione
// il precedente con il paziente posizionato diversamente (testa inclinata, gantry diverso) non trovava lo stesso punto.
async function coregistraStudi(rif, mov, stato) {
  V.offset[rif.img.for] = offsetDi(rif.img.for);
  const r = await coregistra(rif, mov, stato);
  const T0 = offsetDi(mov.img.for);
  V.offset[mov.img.for] = { R: T0.R, t: [T0.t[0] + r.t[0], T0.t[1] + r.t[1], T0.t[2] + r.t[2]] };
  let finale = r.nmi;
  try { const rr = await affinaRotazione(rif, mov, stato); if (rr.nmi > rr.iniziale + 1e-4) { V.offset[mov.img.for] = { ...rr.T, ruotato: true }; finale = rr.nmi; r.gradi = rr.gradi; } }
  catch (e) { console.warn('rotazione della coregistrazione', e); }
  return { ...r, nmi: finale };
}
// sincronizzazione con un esame non ancora allineato: si allinea da solo, una volta, poi si sincronizza
const COREG = { inCorso: null, provati: new Set() };
async function allineaPerSincro(k) {
  const a = P(k); if (!a.img?.ipp || a.img.rgb || COREG.inCorso) return;
  const da = visibili().filter(([b, j]) => j !== k && b.img?.ipp && !b.img.rgb && b.img.for && a.img.for && b.img.for !== a.img.for && !allineate(a.img, b.img) && !COREG.provati.has(a.img.for + '|' + b.img.for));
  { const visti = new Set(); for (let i = da.length - 1; i >= 0; i--) { if (visti.has(da[i][0].img.for)) da.splice(i, 1); else visti.add(da[i][0].img.for); } }
  if (!da.length) return;
  const box = $('#caricamento'), stato = (t) => { box.hidden = false; box.textContent = 'Allineo gli esami per la sincronizzazione · ' + t.replace(/^Coregistrazione: /, ''); };
  COREG.inCorso = (async () => {
    try { for (const [b] of da) { COREG.provati.add(a.img.for + '|' + b.img.for); await coregistraStudi(a, b, stato); } T.allineamenti = (T.allineamenti || 0) + 1; }
    catch (e) { console.error(e); avvisoBreve('Allineamento automatico non riuscito: usa «Allinea» con i punti corrispondenti'); }
    finally { box.hidden = true; COREG.inCorso = null; }
    await sincronizzaDa(V.attivo); aggiornaTabellaMisure(); disegna();
    avvisoBreve('Esami allineati: scorrendo, l\'altro esame resta sullo stesso punto');
  })();
}
$('#btn-auto-allinea').addEventListener('click', () => autoAllinea());
async function autoAllinea() {
  const rif = P(), altri = visibili().map(([p]) => p).filter((p) => p !== rif && p.img?.for && rif.img?.for && p.img.for !== rif.img.for);
  if (!rif.img?.ipp || !altri.length) { alert('Apri in due riquadri due studi diversi (per esempio la TC e la RM): il riquadro attivo è il riferimento.'); return; }
  const box = $('#caricamento'); box.hidden = false; const stato = (t) => { box.textContent = t; };
  try {
    const esiti = [];
    for (const mov of altri) {
      if (mov.img.rgb || rif.img.rgb) continue;
      COREG.provati.add(rif.img.for + '|' + mov.img.for);
      esiti.push(await coregistraStudi(rif, mov, stato));
    }
    T.allineamenti = (T.allineamenti || 0) + 1;
    sincronizzaDa(V.attivo); aggiornaTabellaMisure(); disegna();
    const r = esiti[0];
    if (r) { stato(`Coregistrazione fatta: spostamento ${r.t.map((v) => Math.round(v)).join(', ')} mm${r.gradi ? ` · rotazione ${r.gradi.map((g) => g.toFixed(1)).join('°, ')}°` : ''} · somiglianza ${r.iniziale.toFixed(3)} → ${r.nmi.toFixed(3)}. Se non è precisa, affina con «Allinea» (punti corrispondenti).`); await pausa(2500); }
  } catch (e) { console.error(e); alert('Coregistrazione non riuscita: ' + e.message); }
  finally { box.hidden = true; }
}
