      b.frames = a.frames.map((fa, i) => ({ url: `resl:${si}:${a.sIdx}:${i}:${j}`, virt: true, resl: { vol, src: fa, meta, fuori }, buf: 1, pos: fa.pos, iop: fa.iop, for: fa.for }));
      b.zoom = a.zoom; b.panX = a.panX; b.panY = a.panY; b.rot = a.rot; b.fl = a.fl; b.wc = wc; b.ww = ww; b.wl0 = true;
