  const st = studioDi(cur), altri = V.studi.filter((x) => x.id !== st.id)
    .sort((x, y) => (x.regione !== st.regione) - (y.regione !== st.regione) || Math.abs(x.n - st.n) - Math.abs(y.n - st.n)).slice(0, 3);
  if (!altri.length) { avvisoBreve('In questo caso c\'è un solo esame'); return; }
