  const curIdx = P().sIdx, dritto = P().piano === 'obliqua' ? { frames: P().frames, idx: P().idx } : null;
  V.verticale = false; await impostaRiquadri(1 + scelte.length);
  await selezionaSerie(curIdx, 0);
  if (dritto) { const a0 = P(0); a0.token++; a0.piano = 'obliqua'; a0.frames = dritto.frames; a0.cache.clear(); a0.img = null; await mostraDi(0, dritto.idx, { sincro: false }); }
  for (let k = 0; k < scelte.length; k++) await selezionaSerie(scelte[k], k + 1);
  attiva(0); V.sincro = true; $('#sincro').checked = true; V.confrontoPrec = null; T.confronto = true;
  for (let k = 1; k <= scelte.length; k++) { const q = P(k); if (q.img && P(0).img && famigliaFinestra(q.img) === 'CT' && famigliaFinestra(P(0).img) === 'CT') { q.wc = P(0).wc; q.ww = P(0).ww; } }
  await allineaPerSincro(0); await COREG.inCorso;
  await riallineaPrecedente(true);
