$('#btn-confronta').addEventListener('click', () => confrontaStudi());
$('#btn-riallinea')?.addEventListener('click', () => riallineaPrecedente(!visibili().some(([q, j]) => j > 0 && q.piano === 'riallineato')));
$('#btn-confronta-tutti')?.addEventListener('click', () => confrontaTutti());
async function confrontaStudi({ auto = false } = {}) {
  if (MPR.attivo) modo2D();
  if (V.n < 2 || !V.confrontoPrec) V.confrontoPrec = null;
  // la serie del riquadro attivo; il confronto precedente si continua (esame successivo) solo se si guarda ancora la stessa serie
  if (V.confrontoPrec && P(0).sIdx !== V.confrontoPrec.cur) V.confrontoPrec = null;
  const curIdx = V.confrontoPrec?.cur ?? P().sIdx, cur = V.serie[curIdx]; if (!cur) return;
  const st = studioDi(cur);
  // tutti gli altri esami del caso, di qualsiasi distretto: prima i precedenti (dal più recente al più
  // vecchio, quelli dello stesso distretto per primi), poi gli eventuali successivi. Clic ripetuti: il prossimo.
  const altri = V.studi.filter((x) => x.id !== st.id);
  const prima = altri.filter((x) => x.n < st.n).sort((x, y) => (x.regione !== st.regione) - (y.regione !== st.regione) || y.n - x.n);
  const dopo = altri.filter((x) => x.n > st.n).sort((x, y) => x.n - y.n);
  const lista = [...prima, ...dopo];
  if (!lista.length) { if (!auto) alert('In questo caso c\'è un solo esame: non c\'è niente da affiancare.'); return; }
  const giaId = V.confrontoPrec ? studioDi(V.serie[P(1).sIdx])?.id : null;
  const prec = lista[(lista.findIndex((x) => x.id === giaId) + 1) % lista.length];
  const scelta = serieCorrispondente(cur, prec.id); if (scelta == null) return;
  const dritto = P(0).piano === 'obliqua' && P(0).sIdx === curIdx ? { frames: P(0).frames, idx: P(0).idx } : null;   // encefalo raddrizzato: resta
  await impostaRiquadri(2);
  await selezionaSerie(curIdx, 0); await selezionaSerie(scelta, 1);
  if (dritto) { const a0 = P(0); a0.token++; a0.piano = 'obliqua'; a0.frames = dritto.frames; a0.cache.clear(); a0.img = null; await mostraDi(0, dritto.idx, { sincro: false }); }
  attiva(0); V.sincro = true; $('#sincro').checked = true;
  V.confrontoPrec = { cur: curIdx };
  // stessa finestra nei due esami (se della stessa metodica)
  if (P(0).img && P(1).img && famigliaFinestra(P(0).img) === famigliaFinestra(P(1).img) && famigliaFinestra(P(0).img) === 'CT') { P(1).wc = P(0).wc; P(1).ww = P(0).ww; }
  T.confronto = true;
  // studi diversi non ancora allineati: coregistrazione automatica (TC e RM con le posizioni delle fette)
  const a = P(0).img, b = P(1).img;
  if (a?.ipp && b?.ipp && a.for && b.for && a.for !== b.for && !allineate(a, b) && !a.rgb && !b.rgb) { COREG.provati.delete(a.for + '|' + b.for); await allineaPerSincro(0); await COREG.inCorso; }
  else { sincronizzaDa(0); disegna(); }
  if (a?.ipp && b?.ipp && a.for !== b.for && !a.rgb && !b.rgb && (a.modalita || '') === (b.modalita || '') && /^(CT|MR)$/.test(a.modalita || '') && P(1).frames.length >= 10 && allineate(a, b)) await riallineaPrecedente(true);
  if (auto) avvisoBreve('Esame attuale (A) e precedente (B) affiancati e collegati. «Confronta» passa a un altro esame.');
}
// all'apertura: con un esame precedente dello stesso distretto, i due esami affiancati (se il docente non ha scelto la disposizione)
async function confrontoAutomatico() {
  try {
    if (!V.caso || V.studi.length < 2 || MPR.attivo || window.matchMedia('(max-width: 700px)').matches) return;
    if ((V.caso.disposizione || []).length || V.caso.riquadri >= 1 || V.protoAuto || !$('#ws-mg').hidden) return;
    if (visibili().some(([q]) => studioDi(V.serie[q.sIdx]).id !== studioDi(V.serie[P(0).sIdx]).id)) return;   // già affiancati
    const cur = studioDi(V.serie[P(0).sIdx]);
    if (!V.studi.some((x) => x.id !== cur.id && x.regione === cur.regione)) return;
    if (P(0).img?.modalita === 'US') return;
    attiva(0); await confrontaStudi({ auto: true });
  } catch (e) { console.warn('confronto automatico', e); }
}

// ---------------------------------------------------------------- ASPECTS
const REGIONI_ASPECTS = [['C', 'Caudato'], ['L', 'Lenticolare'], ['IC', 'Capsula interna'], ['I', 'Insula'], ['M1', 'Corteccia ACM anteriore'], ['M2', 'Corteccia ACM laterale'], ['M3', 'Corteccia ACM posteriore'],
  ['M4', 'ACM anteriore (sopraganglionare)'], ['M5', 'ACM laterale (sopraganglionare)'], ['M6', 'ACM posteriore (sopraganglionare)']];
$('#btn-aspects').addEventListener('click', () => {
  if (bloccoEsame()) return;
  const box = $('#aspects'); box.hidden = !box.hidden; if (box.hidden) return;
  box.innerHTML = `<b>ASPECTS</b> <span class="muted small">— spunta le regioni con segni precoci di ischemia (ipodensità, perdita della differenziazione grigia-bianca, rigonfiamento). Livelli: gangliare (C, L, IC, I, M1-M3) e sopraganglionare (M4-M6).</span>
    <div class="aspects-griglia">${REGIONI_ASPECTS.map(([c, n]) => `<label class="check"><input type="checkbox" value="${c}"> <b>${c}</b> ${n}</label>`).join('')}</div>
    <div class="aspects-esito" id="aspects-esito"></div>`;
  const agg = () => { const n = box.querySelectorAll('input:checked').length, v = 10 - n;
    $('#aspects-esito').innerHTML = `Punteggio <b>${v}/10</b>${v <= 7 ? ' · ≤ 7: esteso coinvolgimento, prognosi peggiore e rischio emorragico maggiore dopo trombolisi' : v >= 8 ? ' · ≥ 8' : ''}`; };
  box.querySelectorAll('input').forEach((x) => { x.onchange = agg; }); agg();
});

// ---------------------------------------------------------------- scale internazionali
