  const cardiaco = /cuor|cardi/i.test(c.distretto || '') || (['RM', 'TC'].includes(met) && /(rm|risonanza|tc)\s+(del\s+)?(cardiac|cuore)|cardio[\s-]*(rm|tc)/i.test(c.titolo || '')) || (CLIENT && met === 'RM' && /cuore cardiaco/.test(testo));
