  const tp = tastiPersonali(), strum = Object.fromEntries(['misura', 'roi', 'zoom', 'wl'].map((x) => [tp[x], x]))[k];
  if (strum && !e.shiftKey) { if (scegliStrumento(strum)) avvisoBreve({ misura: 'Distanza', roi: 'ROI ellittica (HU)', zoom: 'Zoom', wl: 'Finestra/livello' }[strum]); return true; }
  const piano = Object.fromEntries(['assiale', 'coronale', 'sagittale'].map((x) => [tp[x], x]))[k];
  if (piano && !e.shiftKey) { pianoRiquadro(piano); return true; }
  if (e.key === ' ') { $('#btn-cine').click(); return true; }
  if (e.key === '?') { mostraTasti(); return true; }
  if (k === 'k' && !e.shiftKey) { catturaChiave(); return true; }
  if (k === 't' && !e.shiftKey) { if (scegliStrumento('nota')) avvisoBreve('Freccia con testo'); return true; }
  if (k === 'b' && !e.shiftKey) return true;   // B + clic sull'immagine: immagine chiave
