// velocità del cine: «auto» = velocità originale dei filmati ecografici (cine_ms), 12 fotogrammi al secondo per le altre serie
const cineMs = () => { const f = $('#cine-fps')?.value; return f && f !== 'auto' ? 1000 / +f : Math.min(250, Math.max(20, +V.serie[P().sIdx]?.cine_ms || 1000 / 12)); };
