  if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { mostra(V.idx - 1); e.preventDefault(); }
  if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { mostra(V.idx + 1); e.preventDefault(); }
  if (e.key === 'Home') { mostra(0); e.preventDefault(); }
  if (e.key === 'End') { mostra(V.frames.length - 1); e.preventDefault(); }
