  const t = await fettaVicina(p.frames, aComuneDa(p.img.for, w), iopComune(p.img)).catch(() => null);
  if (!t || t.scarto > Math.max(3, t.spessore || 0)) { avvisoBreve('Il centro del mirino è fuori dalla serie.'); return; }
  const img = await immagineDi(p, t.i), pt = daPaziente(img, w);
