const PUNTI_MISURA = { linea: ['a', 'b'], profilo: ['a', 'b'], nota: ['a', 'b'], angolo: ['a', 'b', 'c'], recist: ['a', 'b', 'c', 'd'], cobb: ['a', 'b', 'c', 'd'], ict: ['a', 'b', 'c', 'd'], roi: ['a', 'b'] };
