  if ((m.tipo === 'linea' || (m.tipo === 'recist' && !m.d)) && P(k).img) V.ultimaLinea = Math.hypot((m.b.x - m.a.x) * P(k).img.spCol, (m.b.y - m.a.y) * P(k).img.spRow);
