  k.font = F(800, 92); k.fillStyle = '#f8fafc'; k.textAlign = 'center'; k.textBaseline = 'middle'; k.fillText(`${p}%`, cx, cy + 4); k.textBaseline = 'alphabetic';
  centro(EN ? 'Can you do better?' : 'Sai fare meglio?', 1580, F(700, 58), '#f8fafc');
