  let l; try { l = await fetch('/settimana.json', { cache: 'no-cache' }).then((r) => (r.ok ? r.json() : null)); } catch { return; }
  if (!Array.isArray(l)) return;
  const oggi = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Rome' });
