  const richiesta = { reparto: $('#ed-ric-reparto').value.trim(), priorita: $('#ed-ric-priorita').value, lab,
    ...Object.fromEntries(['allergie', 'farmaci', 'dispositivi', 'gravidanza'].map((k) => [k, $('#ed-ric-' + k).value.trim()])) };
  const precedenti = [...qsAll('#ed-prec-lista .ed-prec')].map((el) => ({ data: el.querySelector('.p-data').value.trim(), esame: el.querySelector('.p-esame').value.trim(),
    referto: el.querySelector('.p-referto').value.trim(), ...(el.querySelector('.p-serie').value !== '' ? { serie: +el.querySelector('.p-serie').value } : {}), didattico: el.querySelector('.p-didattico').checked })).filter((x) => x.referto);
  const liv = $('#ed-com-livello').value;
  const comunicazione = liv ? { livello: liv, accettabili: [...qsAll('#ed-com-acc input:checked')].map((x) => x.value).filter((x) => x !== liv),
    destinatari: [...qsAll('#ed-com-dest input:checked')].map((x) => x.value), parole: $('#ed-com-parole').value.split(',').map((x) => x.trim()).filter(Boolean), motivo: $('#ed-com-motivo').value.trim() } : null;
