const leggiProtocollo = () => { try { return JSON.parse(localStorage.getItem('quiz-protocollo') || '{}'); } catch { return {}; } };
function statProtocollo() { const v = Object.values(leggiProtocollo()); return { n: v.length, media: v.length ? Math.round(v.reduce((a, b) => a + b, 0) / v.length) : 0 }; }
// punteggio di una domanda: una risposta = 1 se giusta, 0,5 se accettabile; più risposte = giuste trovate meno le sbagliate
function puntiDomanda(d, scelte) {
  const g = new Set(d.giuste), a = new Set(d.accettabili || []);
  if (d.id === 'fasi' || d.id === 'prec') {
    let p = 0; for (const x of scelte) p += g.has(x) ? 1 : a.has(x) ? 0 : -0.5;
    return Math.max(0, Math.min(1, p / g.size));
  }
  return g.has(scelte[0]) ? 1 : a.has(scelte[0]) ? 0.5 : 0;
}
async function apriProtocollo() {
  try { PROTOCOLLI ||= await fetch('protocolli.json', { cache: 'no-cache' }).then((r) => r.json()); } catch { $('#esame-corpo').innerHTML = '<p class="stato ko">Scenari non disponibili.</p>'; return; }
  const fatti = leggiProtocollo(), ordine = [...PROTOCOLLI.scenari].sort((a, b) => (a.id in fatti) - (b.id in fatti) || Math.random() - 0.5);
  let i = 0;
  const mostra = () => {
    const sc = ordine[i], r = sc.richiesta, O = PROTOCOLLI.opzioni;
    const classe = { PS: 'urgenza dal Pronto soccorso', R: 'paziente ricoverato, urgente', U: 'ricetta classe U · entro 72 ore', B: 'ricetta classe B · entro 10 giorni', D: 'ricetta classe D · entro 60 giorni (esami strumentali)', P: 'ricetta classe P · programmata' }[r.priorita] || r.priorita;
    $('#esame-corpo').innerHTML = `<h1>🧾 Giustificazione e protocollo</h1>
      <p class="muted">Scenario ${i + 1} di ${ordine.length} · ${esc(PROTOCOLLI.nota)}</p>
      <div class="impegnativa"><div class="imp-testa"><b>Richiesta di esame</b><span>${esc(r.reparto)} · ${esc(classe)}</span></div>
        <div class="imp-righe"><div><span>Paziente</span>${r.sesso === 'F' ? 'Donna' : 'Uomo'}, ${r.eta} anni</div>
        <div><span>Esame richiesto</span><b>${esc(r.richiesto)}</b></div>
        <div><span>Quesito</span>${esc(r.quesito)}</div><div><span>Notizie cliniche</span>${esc(r.storia)}</div>
        ${r.lab?.length ? `<div><span>Esami di laboratorio</span>${r.lab.map(([n, v]) => `${esc(n)} <b>${esc(v)}</b>`).join(' · ')}</div>` : ''}
        <div><span>Allergie</span>${esc(r.allergie)}</div><div><span>Dispositivi impiantati</span>${esc(r.dispositivi)}</div><div><span>Gravidanza</span>${esc(r.gravidanza)}</div></div></div>
      <form id="pr-form">${sc.domande.map((d) => { const multi = d.id === 'fasi' || d.id === 'prec';
        return `<fieldset class="pr-domanda" data-d="${d.id}"><legend>${esc(d.testo)}</legend>${O[d.id].map(([v, t]) => `<label class="check"><input type="${multi ? 'checkbox' : 'radio'}" name="pr-${d.id}" value="${v}"> ${esc(t)}</label>`).join('')}<div class="pr-esito"></div></fieldset>`; }).join('')}</form>
      <div id="pr-fine" hidden></div>
      <p><button id="pr-conferma" class="primary">Conferma</button> <a href="#/">Torna all'elenco</a></p>`;
    $('#pr-conferma').onclick = () => {
      const scelte = (d) => [...qsAll(`[name="pr-${d.id}"]:checked`)].map((x) => x.value);
      const manca = sc.domande.find((d) => !scelte(d).length);
      if (manca) { avvisoBreve(`Rispondi anche a: «${manca.testo}»`); return; }
      let tot = 0;
      for (const d of sc.domande) {
        const p = puntiDomanda(d, scelte(d)); tot += p;
        const fs = qs1(`.pr-domanda[data-d="${d.id}"]`), nome = (v) => O[d.id].find((x) => x[0] === v)?.[1] || v;
        fs.classList.add(p >= 1 ? 'ok' : p > 0 ? 'parz' : 'ko');
        fs.querySelectorAll('input').forEach((x) => { x.disabled = true; const l = x.closest('label'); if (d.giuste.includes(x.value)) l.classList.add('giusta'); else if ((d.accettabili || []).includes(x.value)) l.classList.add('accettabile'); else if (x.checked) l.classList.add('sbagliata'); });
        fs.querySelector('.pr-esito').innerHTML = p >= 1 ? '✓ Corretto' : `${p > 0 ? '≈ In parte' : '✗ No'}: ${d.giuste.map(nome).map(esc).join('; ')}${d.accettabili?.length ? ` <span class="muted">(accettabile anche: ${d.accettabili.map(nome).map(esc).join('; ')})</span>` : ''}`;
      }
      const pc = Math.round(100 * tot / sc.domande.length), f = leggiProtocollo(); f[sc.id] = pc;
      try { localStorage.setItem('quiz-protocollo', JSON.stringify(f)); } catch {}
      $('#pr-fine').hidden = false;
      $('#pr-fine').innerHTML = `<div class="esame-sintesi"><div><div class="grande" style="color:${pc >= 75 ? 'var(--ok)' : pc >= 50 ? 'var(--warn)' : 'var(--ko)'}">${pc}%</div><small>questo scenario</small></div></div>
        <div class="spiegazione">${esc(sc.spiegazione)}</div><p class="muted small">Fonte: ${esc(sc.fonte)}</p>`;
      $('#pr-conferma').textContent = i + 1 < ordine.length ? 'Prossimo scenario →' : 'Fine: riepilogo';
      $('#pr-conferma').onclick = () => { if (++i < ordine.length) mostra(); else riepilogo(); };
      $('#pr-fine').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    };
  };
  const riepilogo = () => {
    const f = leggiProtocollo(), st = statProtocollo();
    $('#esame-corpo').innerHTML = `<h1>🧾 Giustificazione e protocollo: riepilogo</h1><p>Media ${st.media}% su ${st.n} scenari.</p>
      <table class="tab-esame"><thead><tr><th>Scenario</th><th>Ultimo punteggio</th></tr></thead><tbody>${PROTOCOLLI.scenari.map((s) => `<tr><td>${esc(s.titolo)}</td><td>${s.id in f ? f[s.id] + '%' : '—'}</td></tr>`).join('')}</tbody></table>
      <p><button id="pr-ancora" class="primary">Ricomincia</button> <a href="#/">Torna all'elenco</a></p>`;
    $('#pr-ancora').onclick = () => apriProtocollo();
  };
  mostra();
}
function htmlStoricoGuardia(lista) {
  const t = (lista || []).filter((e) => ['guardia', 'lista'].includes(e.livello));
  if (!t.length) return '<p class="muted small">Nessun turno svolto.</p>';
  return `<table class="tab-esame"><thead><tr><th>Data</th><th>Sessione</th><th>Casi</th><th>Punteggio automatico</th><th>Discrepanze maggiori</th><th>Minori</th><th>Da rivedere dal docente</th></tr></thead><tbody>${t.map((e) => {
    const d = e.discrepanze || {};
    return `<tr><td>${esc(String(e.data).slice(0, 10).split('-').reverse().join('/'))}</td><td>${e.livello === 'lista' ? '📋 Lista di lavoro' : '🚑 Guardia'}</td><td>${e.svolti}/${e.n}</td><td>${e.punteggio}%</td>
      <td class="${d.maggiori ? 'ko' : ''}"><b>${d.maggiori ?? '—'}</b></td><td>${d.minori ?? '—'}</td><td>${d.daRivedere ? d.daRivedere : '—'}</td></tr>`; }).join('')}</tbody></table>`;
}
function casiLivello(liv) {
  // esami di livello: solo casi dell'origine di base (regole fisse, risultati confrontabili nel tempo)
  const pool = (d) => elencoProfilo().filter((c) => c.visibile !== false && origineDi(c) === origineBase() && (c.difficolta || 'Intermedio') === d);
  const scelti = [];
  for (const [d, n] of Object.entries(LIVELLI_ESAME[liv])) {
    // a rotazione tra le metodiche, per non avere 10 mammografie
    const per = {}; for (const c of pool(d).sort(() => Math.random() - 0.5)) (per[metodicaDi(c)] ||= []).push(c.id);
    const code = Object.values(per).sort(() => Math.random() - 0.5); let k = 0;
    while (k < n && code.some((q) => q.length)) for (const q of code) if (q.length && k < n) { scelti.push(q.shift()); k++; }
  }
  if (liv === 'Misto' && scelti.length < ESAME_N) for (const c of pool('Intermedio').sort(() => Math.random() - 0.5)) { if (scelti.length >= ESAME_N) break; if (!scelti.includes(c.id)) scelti.push(c.id); }
  return scelti.sort(() => Math.random() - 0.5);
}
let ESAMI_MIEI = null;
async function storicoEsami() { if (!CLOUD || ADMIN) return []; try { ESAMI_MIEI = await getJSON('/api/esami'); } catch { ESAMI_MIEI = []; } return ESAMI_MIEI; }
function htmlStoricoEsami(lista) {
  const liv = lista.filter((e) => !['libero', 'pre', 'post', 'guardia', 'lista'].includes(e.livello));
  if (!liv.length) return '<p class="muted small">Nessun esame di livello ancora: il primo diventa il tuo punto di partenza.</p>';
  const col = (p) => (p >= 75 ? 'var(--ok)' : p >= 50 ? 'var(--warn)' : 'var(--ko)');
  const per = {}; for (const e of liv) (per[e.livello] ||= []).push(e);
  return `<table class="tab-esame es-storico"><thead><tr><th>Livello</th><th>Esami</th><th>Primo</th><th>Ultimo</th><th>Migliore</th><th>Andamento</th></tr></thead><tbody>${Object.entries(per).map(([l, v]) => {
    const pts = v.map((e) => e.punteggio), w = 120, h = 26, x = (i) => (v.length === 1 ? w / 2 : 4 + i * (w - 8) / (v.length - 1)), y = (p) => h - 3 - p / 100 * (h - 6);
    const d = Math.round(pts[pts.length - 1] - pts[0]);
    return `<tr><td><b>${esc(l)}</b></td><td>${v.length}</td><td>${pts[0]}% <small class="muted">${esc(v[0].data.slice(0, 10).split('-').reverse().join('/'))}</small></td>
      <td style="color:${col(pts[pts.length - 1])};font-weight:600">${pts[pts.length - 1]}%</td><td>${Math.max(...pts)}%</td>
      <td><svg width="${w}" height="${h}" class="spark" aria-label="andamento"><polyline fill="none" stroke="currentColor" stroke-width="1.5" points="${pts.map((p, i) => `${x(i)},${y(p)}`).join(' ')}"/>${pts.map((p, i) => `<circle cx="${x(i)}" cy="${y(p)}" r="2"/>`).join('')}</svg>
      ${v.length > 1 ? `<small>${d > 0 ? '+' : ''}${d} punti</small>` : ''}</td></tr>`; }).join('')}</tbody></table>`;
}
