    if (Q.mostra) { nuovaDomandaAnatomia(); return; }
    Q.fatte++; Q.mostra = { id: Q.target, ok: false }; disegnaQuizAnatomia('Eccola, evidenziata in giallo (scorri per vederla tutta)'); vaiAllaStruttura(Q.target); disegna();
