  const c = document.createElement('canvas'); c.width = r.larghezza; c.height = r.altezza;
  const cx = c.getContext('2d'), id = cx.createImageData(r.larghezza, r.altezza), lo = r.voi.lower, sc = 255 / Math.max(1, r.voi.upper - r.voi.lower);
