  const val = r.profilo.filter(Boolean), max = Math.max(...val.map((x) => x.dmax), r.riferimento || 1) * 1.1, X = (s) => 30 + (s / Math.max(1, r.lunghezza)) * (w - 40), Y = (d) => h - 14 - (d / max) * (h - 24);
