  for (let d = 0; d <= max; d += max > 20 ? 10 : 5) { k.fillText(`${d}`, 4, Y(d) + 3); k.strokeStyle = 'rgba(255,255,255,.08)'; k.beginPath(); k.moveTo(30, Y(d)); k.lineTo(w - 10, Y(d)); k.stroke(); }
