// ---------------------------------------------------------------- suggerimenti sotto i tasti del visualizzatore
// Al posto del tooltip del browser (che compare vicino al puntatore e copre l'immagine) un'etichetta
// sotto il tasto, centrata e dentro lo schermo. Il title resta sull'elemento per l'accessibilità.
(() => {
  const tip = document.createElement('div'); tip.className = 'tip-barra'; tip.setAttribute('role', 'tooltip'); tip.hidden = true;
  document.body.appendChild(tip);
  let su = null, timer = null;
  const nascondi = () => {
    clearTimeout(timer); tip.hidden = true;
    if (su) { if (!su.getAttribute('title') && su.dataset.tip) su.setAttribute('title', su.dataset.tip); su = null; }
  };
  document.addEventListener('pointerover', (e) => {
    if (e.pointerType === 'touch') return;
    const el = e.target.closest('.barra-unica [title], .barra-unica [data-tip]');
    if (el === su) return;
    nascondi();
    if (!el) return;
    const testo = el.getAttribute('title') || el.dataset.tip; if (!testo) return;
    su = el; el.dataset.tip = testo; el.removeAttribute('title');             // niente tooltip del browser
    timer = setTimeout(() => {
      if (su !== el) return;
      tip.textContent = testo; tip.hidden = false;
      const r = el.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
      let x = r.left + r.width / 2 - w / 2; x = Math.max(6, Math.min(innerWidth - w - 6, x));
      let y = r.bottom + 6; if (y + h > innerHeight - 4) y = r.top - h - 6;
      tip.style.left = `${x}px`; tip.style.top = `${y}px`;
      tip.style.setProperty('--freccia', `${r.left + r.width / 2 - x}px`);
    }, 300);
  });
  document.addEventListener('pointerdown', nascondi, true);
  document.addEventListener('scroll', nascondi, true);
  window.addEventListener('blur', nascondi);
})();
