  const f = CL.sorgenti?.find((x) => x.size > 132), h = f && await intestazioneStudio(f); if (!h || (!h.pid && !h.nome)) return;
  const stesso = (v) => v.uid && v.uid !== h.uid && ((h.pid && v.pid === h.pid) || (!h.pid && h.nome && v.nome === h.nome && v.nascita === h.nascita));
