      CL.file.push(voceFile);
      if (!mf) { ps.voci.push({ file: f, sorgente: f, voceFile, istanza: info.istanza, posizione: info.posizione, ipp: info.ipp, iop: info.iop, tempo: info.tempo }); nImm++; }
