function pulisciHTML(h) {
  const t = document.createElement('template'); t.innerHTML = h || '';
  const OK = new Set(['P', 'DIV', 'BR', 'B', 'STRONG', 'I', 'EM', 'U', 'UL', 'OL', 'LI', 'H3', 'SPAN']);
  const visita = (n) => { for (const c of [...n.childNodes]) { if (c.nodeType === 1) { if (!OK.has(c.tagName)) { c.replaceWith(...c.childNodes); continue; } for (const a of [...c.attributes]) c.removeAttribute(a.name); visita(c); } else if (c.nodeType !== 3) c.remove(); } };
  visita(t.content); return t.innerHTML;
}
function impostaEditor(html, pulisci) { $('#ref-testo').innerHTML = pulisci ? pulisciHTML(html) : html; }
function aggiungiAlEditor(html) {
  const ed = $('#ref-testo'), sel = docRef().getSelection();
  if (sel.rangeCount && ed.contains(sel.anchorNode)) { ed.focus(); docRef().execCommand('insertHTML', false, html); }
  else ed.insertAdjacentHTML('beforeend', html);
}
function comandoEditor(cmd) {
  const ed = $('#ref-testo'); ed.focus();
  const D = docRef();
  if (cmd === 'titolo') { const b = D.queryCommandValue('formatBlock'); D.execCommand('formatBlock', false, /h3/i.test(b) ? 'p' : 'h3'); }
  else if (cmd === 'maiuscolo') { const t = D.getSelection().toString(); if (t) D.execCommand('insertText', false, t.toUpperCase()); }
  else D.execCommand(cmd, false, null);
  salvaBozzaReferto();
}
// editor → blocchi per PDF e Word: [{ tipo: 'p' | 'h' | 'li' | 'oli', n, runs: [{ t, b, i, u }] }]
function blocchiDaEditor(ed) {
  const out = [];
  const runs = (n, st, acc) => {
    for (const c of n.childNodes) {
      if (c.nodeType === 3) { if (c.textContent) acc.push({ t: c.textContent.replace(/\u00a0/g, ' '), ...st }); continue; }
      if (c.nodeType !== 1) continue;
      const tg = c.tagName, s2 = { ...st };
      if (tg === 'BR') { acc.push({ t: '\n', ...st }); continue; }
      if (tg === 'B' || tg === 'STRONG' || +getComputedStyle(c).fontWeight >= 600) s2.b = true;
      if (tg === 'I' || tg === 'EM' || getComputedStyle(c).fontStyle === 'italic') s2.i = true;
      if (tg === 'U' || /underline/.test(getComputedStyle(c).textDecorationLine)) s2.u = true;
      runs(c, s2, acc);
    }
    while (acc.length && acc[acc.length - 1].t === '\n') acc.pop();
    return acc;
  };
  const blocco = (n) => {
    const tg = n.nodeType === 1 ? n.tagName : '#';
    if (tg === '#') { if (n.textContent.trim()) out.push({ tipo: 'p', runs: [{ t: n.textContent }] }); return; }
    if (tg === 'UL' || tg === 'OL') { [...n.children].forEach((li, i) => out.push({ tipo: tg === 'UL' ? 'li' : 'oli', n: i + 1, runs: runs(li, {}, []) })); return; }
    if (/^H[1-6]$/.test(tg)) { out.push({ tipo: 'h', runs: runs(n, {}, []) }); return; }
    if ((tg === 'DIV' || tg === 'P') && n.querySelector('ul,ol,p,div,h3')) { for (const c of n.childNodes) blocco(c); return; }
    if (tg === 'BR') { out.push({ tipo: 'p', runs: [] }); return; }
    out.push({ tipo: 'p', runs: runs(n, {}, []) });
  };
  for (const c of ed.childNodes) blocco(c);
  return out;
}
// codice fiscale: 16 caratteri con il carattere di controllo finale (anche con omocodie)
function cfValido(cf) {
  cf = String(cf || '').toUpperCase();
  if (!/^[A-Z]{6}[0-9LMNPQRSTUV]{2}[A-Z][0-9LMNPQRSTUV]{2}[A-Z][0-9LMNPQRSTUV]{3}[A-Z]$/.test(cf)) return false;
  const D = { 0: 1, 1: 0, 2: 5, 3: 7, 4: 9, 5: 13, 6: 15, 7: 17, 8: 19, 9: 21, A: 1, B: 0, C: 5, D: 7, E: 9, F: 13, G: 15, H: 17, I: 19, J: 21, K: 2, L: 4, M: 18, N: 20, O: 11, P: 3, Q: 6, R: 8, S: 12, T: 14, U: 16, V: 10, W: 22, X: 25, Y: 24, Z: 23 };
  let t = 0;
  for (let i = 0; i < 15; i++) { const c = cf[i]; t += i % 2 ? (/\d/.test(c) ? +c : c.charCodeAt(0) - 65) : D[c]; }
  return String.fromCharCode(65 + (t % 26)) === cf[15];
}
function controllaCF() {
  const el = $('#ref-cf'), v = el.value.trim().toUpperCase(), out = $('#ref-cf-esito');
  if (el.value !== v && document.activeElement !== el) el.value = v;
  out.textContent = !v ? '' : cfValido(v) ? '✓ valido' : v.length < 16 ? '' : '⚠ controlla: carattere finale o formato non corretti';
  out.className = 'ref-cf-esito ' + (v && cfValido(v) ? 'ok' : v.length >= 16 ? 'ko' : '');
}
