// ---------------------------------------------------------------- annotazioni salvate a mano (come nei PACS: «Salva annotazioni esame / serie»)
// Misure, frecce e note restano finché l'esame è aperto; alla riapertura si ritrovano solo quelle salvate. Chiudendo con
// annotazioni non salvate si chiede che cosa fare. Sulla barra di scorrimento una «A» segna le immagini con annotazioni
// (gialla se non salvate) e un numero le immagini chiave: un clic porta all'immagine.
function chiaveAnnSalvate() {
  if (CLIENT) return CL.chiave && !CL.finestra && V.caso?.id === 'locale' ? 'rq-misure:' + CL.chiave : null;
  if ($('#annota-barra') || FINESTRA_N) return null;               // doppia lettura del docente o finestra aggiunta: niente da salvare
  return V.caso?.id && V.caso.id !== 'locale' && !$('#vista-caso').hidden ? `rq-ann:${UTENTE?.id || 'ospite'}:${V.caso.id}` : null;
}
// le misure del docente (mostrate dopo la risposta) non sono annotazioni proprie
function misureProprie() { const o = {}; for (const [k, l] of Object.entries(V.misure || {})) { const x = (l || []).filter((m) => !m.docente); if (x.length) o[k] = x; } return o; }
