// archivio delle immagini chiave della piattaforma (IndexedDB, in questo browser)
function dbIC(modo, k, v) {
  return new Promise((ok, ko) => {
    const r = indexedDB.open('rq-annotazioni', 1);
    r.onupgradeneeded = () => r.result.createObjectStore('chiavi');
    r.onerror = () => ko(r.error);
    r.onsuccess = () => { const db = r.result, tx = db.transaction('chiavi', modo === 'get' ? 'readonly' : 'readwrite'), st = tx.objectStore('chiavi');
      const q = modo === 'get' ? st.get(k) : modo === 'put' ? st.put(v, k) : st.delete(k);
      q.onsuccess = () => ok(q.result); q.onerror = () => ko(q.error); tx.oncomplete = () => db.close(); };
  });
}
async function ritrovaAnnotazioni() {
  ANN.salvate = {}; ANN.firma = ''; ANN.icFirma = '[]';
  const k = chiaveAnnSalvate();
  if (k && !CLIENT) try {
    const l = await dbIC('get', k);
    if (Array.isArray(l) && l.length) { IC.lista = l; IC.nascosta = false; salvaIC(); disegnaIC(); ANN.icFirma = firmaIC(l); ANN.icSalvate = l.slice(); }
  } catch (e) { console.warn('immagini chiave salvate', e); }
  if (k) try {
    const m = CLIENT ? leggiMisureClient() : JSON.parse(localStorage.getItem(k) || 'null');
    if (m && Object.keys(m).length) {
      ANN.salvate = m; const doc = Object.fromEntries(Object.entries(V.misure || {}).map(([kk, l]) => [kk, (l || []).filter((x) => x.docente)]).filter(([, l]) => l.length));
      V.misure = JSON.parse(JSON.stringify(m)); for (const [kk, l] of Object.entries(doc)) (V.misure[kk] ||= []).push(...l);
      disegna(); try { aggiornaTabellaMisure(); } catch {}
      avvisoBreve('Ritrovate le annotazioni salvate di questo esame (le «A» sulla barra di scorrimento).');
    }
  } catch {}
  aggiornaStatoAnn();
}
