// ---- telefono: pannello delle domande a «foglio» in basso con tre altezze (ridotto, metà, pieno)
const FOGLIO = { stati: ['14dvh', '48dvh', '88dvh'], i: 1 };
const telefono = () => matchMedia('(max-width:700px)').matches;
function foglio(i) {
  const q = qs1('.caso>.quiz'); if (!q) return;
  const on = telefono() && !$('#vista-caso').hidden;
  document.body.classList.toggle('foglio-attivo', on);
  if (!on) return;
  if (!q.querySelector('.q-maniglia')) {
    const m = document.createElement('div'); m.className = 'q-maniglia'; m.title = 'Tocca per allargare o ridurre le domande';
    m.innerHTML = '<span class="qm-tit"></span><button type="button" class="ghost qm-giu" aria-label="Riduci">▾</button><button type="button" class="ghost qm-su" aria-label="Allarga">▴</button>';
    q.prepend(m);
    m.querySelector('.qm-giu').onclick = (e) => { e.stopPropagation(); foglio(Math.max(0, FOGLIO.i - 1)); };
    m.querySelector('.qm-su').onclick = (e) => { e.stopPropagation(); foglio(Math.min(2, FOGLIO.i + 1)); };
    m.onclick = () => foglio((FOGLIO.i + 1) % 3);
    // trascinamento della maniglia con il pollice
    let y0 = null; m.addEventListener('touchstart', (e) => { y0 = e.touches[0].clientY; }, { passive: true });
    m.addEventListener('touchend', (e) => { if (y0 == null) return; const d = e.changedTouches[0].clientY - y0; y0 = null; if (Math.abs(d) > 30) foglio(Math.max(0, Math.min(2, FOGLIO.i + (d < 0 ? 1 : -1)))); }, { passive: true });
  }
  if (i != null) FOGLIO.i = i;
  document.documentElement.style.setProperty('--foglio', FOGLIO.stati[FOGLIO.i]);
  q.querySelector('.qm-tit').textContent = $('#btn-conferma').dataset.stato === 'fatto' ? 'Esito e correzione' : ($('#q-titolo')?.textContent || 'Domande');
  window.dispatchEvent(new Event('resize'));        // il visualizzatore ridisegna le immagini alla nuova altezza
}
matchMedia('(max-width:700px)').addEventListener('change', () => foglio());
window.addEventListener('hashchange', () => setTimeout(() => foglio(location.hash.startsWith('#/caso/') ? 1 : null), 300));
new MutationObserver(() => { if (telefono() && !$('#q-esito').hidden && FOGLIO.i < 2) foglio(2); }).observe($('#q-esito'), { attributes: true, attributeFilter: ['hidden'] });
